        self.spawn_biome_type.encode(buf)?;
        let bytes = (&self.user_defined_biome_name).as_bytes();
        let len = bytes.len();
        crate::bedrock::codec::VarInt(len as i32).encode(buf)?;
        buf.put_slice(bytes);
